Method.Implementation:
	Set SQLCODE=0, tSC=$$$OK
	WRITE !, "GetPurgeSet: Recursion # " _ ..tblNum _ " / Table: " _ tbl _ ", All: " _ allRows
	set ..tblNum =  ..tblNum + 1
	set origSchema = schema
	set origTbl = tbl
	// Get columns in the table
	IF (..GetDataSet(.pDtSet, schema , tbl , rowID ) > 0)
	{
		Set result = ##class(%ResultSet).%New("%SQL.Manager.Catalog:Fields")
	 	set sc = result.Execute( schema, tbl)
	 	If $$$ISERR(sc) Do DisplayError^%apiOBJ(sc) Quit

	    set leafTbl = 1
	    // Go over each column and check if this is a reference table
	 	While (result.Next(.sc)) {

			If $$$ISERR(sc) {
				Quit
			}
			set pDtSet(tbl) = rowID

		 	// do result.%Print()
		 	set fld = result.Data("FIELD_NAME")
		 	set ref = result.Data("REFERENCE_TO")
		 	set dtTy = result.Data("DATATYPE")
		 	set tblNm = ""

		 	// WRITE !, "Table: " _ tbl _ " - Column: " _ fld _ ", REF " _ ref _", data type: " _ dtTy _ ", ID: " _ $DATA(pDtSet(tbl _ fld))

			// Go to next column if ID is not found
			if ($DATA(pDtSet(tbl _ fld))  = 0)
			{
				CONTINUE
			}
		 	elseif $L(ref) > 0
		 	{
			 	// references another table, get schema and table
		 		set tblNm = $EXTRACT(ref, $F(ref, "."), *)
		 		set schema = $EXTRACT(ref, 1, $F(ref, ".")-2)
		 		// WRITE !, "REF: Parent: " _ tbl _", Ref Table: " _ tblNm _ " in schema: " _ schema
		 	}
		 	elseif $L(dtTy) > 0
		 	{
			 	// Data type is key to another table which is not BASIC type (NOT starting with %)
			 	if ($F(dtTy, "%") '= 2)
			 	{
				 	// FIND LAST . and get last part as table, replace . with _ in first part to get schema
				 	SET lastPos=$LENGTH(dtTy)+2-$FIND($REVERSE(dtTy),".")
					set tblNm = $EXTRACT(dtTy, lastPos+1, *)
					set schema = $REPLACE($EXTRACT(dtTy, 1, lastPos-1), ".", "_")
		 			// WRITE !, "DTTY: Parent: " _ tbl _", Ref Table: " _ tblNm _ " in schema: " _ schema
			 	}

		 	}
		 	else
		 	{
			   // WRITE !, fld _ "has NO refs"
		 	}

		 	// Found a referenced table
		 	if ($L(tblNm) > 0)
		 	{
			 	set tblNmId = $GET(pDtSet(tbl _ fld))
			 	if tblNmId > 0
			 	{
			 		// WRITE !, "Get data from table: " _ tblNm _ " ID: " _ tblNmId
			 		// Multiple IDs
			 		if ($LENGTH(tblNmId,",") > 0) 
			 		{
			 			SET countup=1
			 			SET countdown=$LENGTH(tblNmId,",")
				    	FOR reps=countdown:-1:1 {
				      		SET extract=$PIECE(tblNmId,",", countup)
	  			      		set id =  $ZStrip(extract,"<>WC")

	  			      		// Call self on this table for each ID
				      		Do ..GetPurgeSet(.pSet, schema, tblNm, id, allRows)
				      		SET countup=countup+1
				    	}
				    }
				    Else 
				    {		
				    	// Call self on this table	   
					    Do ..GetPurgeSet(.pSet, schema, tblNm, tblNmId, allRows)
				    }

		 	 		set leafTbl = 0
			 	}
			 	else
			 	{
				 	// WRITE !, schema _ "." _ tblNm _", ID is NULL" _ tblNmId
			 	}
		 	}

	 	}
	}
 set ..tblNum = ..tblNum - 1
 if ($DATA(pDtSet(tbl _ "ID")) '= 0)
 {
	 if (tbl = origTbl)
	 {
		 DO ..PurgeData(origSchema, origTbl, $GET(pDtSet(origTbl _ "ID")), allRows)
	 }
	 else
	 {
 		DO ..PurgeData(schema, tbl, $GET(pDtSet(tbl _ "ID")), allRows)
	 }

 	if leafTbl = 1
 	{
	 	// WRITE !, "LEAF TABLE: " _ tbl _ ", ID: " _ $GET(pDtSet(tbl _ "ID")), !
 	}
 	else
 	{
	 // WRITE !, "GetPurgeSet Processed: Recursion # " _ ..tblNum _ ": "  _ tbl _ ", ID: " _ $GET(pDtSet(tbl _ "ID")), !
 	}
 	Set pSet(..tblNum _ "." _ tbl _ "-" _ $GET(pDtSet(tbl _ "ID"))) = "Purged" 
 }
 return $$$OK

    set numRows = 0
  	SET myquery = "SELECT * FROM " _ schema _ "." _ tbl _ " where ID = ?"
  	// WRITE !, "GetDataSet: SQL: " _ myquery _ " / " _ rId
  	SET tStatement = ##class(%SQL.Statement).%New()
	set tSC = tStatement.%Prepare(myquery)
	set rset = tStatement.%Execute(rId)
	While rset.%Next(.tSC) && $$$ISOK(tSC) {
		//   WRITE !, rset.%GetMetadata().columns.Count() 
		// Get data for all columns for the table
		for i=1:1:rset.%GetMetadata().columns.Count() {
			set numRows = numRows + 1
    		set colNm =  rset.%GetMetadata().columns.GetAt(i)
    		//   WRITE !, colNm.colName 
			Set tVal = $ZStrip(rset.%Get(colNm.colName),"<>WC")

			SET delim=" "
			set val = ""
   			SET countdown=$LENGTH(tVal,"	")
			   SET countup=1
			   FOR reps=countdown:-1:1 {
			      SET extract=$PIECE(tVal,"	", countup)
			      if (countup = 1)
			      {
				      set val =  $ZStrip(extract,"<>WC")
			      }
			      else
			      {
			      	set val =  val _ ", " _ $ZStrip(extract,"<>WC")
			      }
			      SET countup=countup+1
			   }

			   // Set the data for the column
			   if ($LENGTH(val) > 0)
			   {
				    // WRITE !, "    " _tbl _ "/" _ colNm.colName _ ": " _ val
			   		set pDataSet(tbl _ colNm.colName) = val
			   }
		}
	}
	//   WRITE !, tSC _ ", " _ rset
   	return numRows

   if (allRows = 1)
   {
		SET myquery = "DELETE %NOLOCK FROM " _ schema _ "." _ tbl _ " where ID < ?"
   }
   else
   {
  		SET myquery = "DELETE FROM " _ schema _ "." _ tbl _ " where ID = ?"
   }
  	WRITE !, $NAMESPACE _ ", * PurgeData: SQL: " _ myquery _ " / " _ rId _ ", All: " _ allRows

  	SET tStatement = ##class(%SQL.Statement).%New()
	set qStatus = tStatement.%Prepare(myquery)
	IF qStatus'=1 { WRITE !, "SQL %Prepare failed:" DO $System.Status.DisplayError(qStatus) QUIT}
	set rset = tStatement.%Execute(rId)
	// WRITE !, "Execute Delete: " _ rset.%SQLCODE
	IF rset.%SQLCODE=0 { QUIT $$$OK }
	return $$$ERROR(rset.%SQLCODE _" " _ rset.%Message)

	return $$$OK

SET $NAMESPACE = "DEMOGRAPHICS"
set numCls = 0

set purgeObj = ##class(IHC.ITF.ITFCOMMON.Util.PurgeClasses).%New()
Do purgeObj.GetPurgeSet(.pSet, "IHC_ITF_Request", "insertUpdatePersonRequest", rowID, 1)
// Do purgeObj.GetPurgeSet(.pSet, "IHC_ITF_Response", "insertUpdatePersonResponse", rowID, 1)

 set num =1
   SET key=$ORDER(pSet(""))
  WHILE (key'="") {
    // WRITE !, num _ ". " _ key _ ": " _ $G(pSet(key))
    // Get next subscript 
    SET key = $ORDER(pSet(key))
    set num = num +1
  }
QUIT $$$OK
